import re
from collections import defaultdict

def parse_log_file(filepath):
    pattern = r'^(?P<timestamp>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) \[(?P<level>\w+)\] (?P<message>.*)$'
    results = []
    error_count = 0
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            match = re.match(pattern, line)
            if match:
                results.append(match.groupdict())
            else:
                error_count += 1
    summary = {
        'total_entries': len(results),
        'errors': error_count,
        'entries': results
    }
    return summary

def generate_summary(summary):
    level_counts = defaultdict(int)
    for entry in summary['entries']:
        level_counts[entry['level']] += 1
    return {
        'summary': summary,
        'level_distribution': dict(level_counts)
    }

if __name__ == '__main__':
    data = parse_log_file('server.log')
    summary = generate_summary(data)
    print(summary)

import re
import json
from datetime import datetime
from collections import defaultdict

def parse_log_file(filepath):
    pattern = r'^(?P<timestamp>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) \[(?P<level>\w+)\] (?P<message>.*)$'
    results = []
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            match = re.match(pattern, line)
            if match:
                results.append(match.groupdict())
    return results

def filter_by_date(entries, start_date, end_date):
    filtered = []
    for entry in entries:
        try:
            dt = datetime.strptime(entry['timestamp'], '%Y-%m-%d %H:%M:%S')
            if start_date <= dt <= end_date:
                entry['parsed_datetime'] = dt.isoformat()
                filtered.append(entry)
        except ValueError:
            continue
    return filtered

def export_json(data, filepath):
    with open(filepath, 'w') as f:
        json.dump(data, f, indent=2, default=str)

def generate_statistics(entries):
    stats = defaultdict(int)
    for entry in entries:
        stats[entry['level']] += 1
    return dict(stats)

if __name__ == '__main__':
    raw = parse_log_file('server.log')
    start = datetime(2023, 6, 1)
    end = datetime(2023, 6, 30)
    filtered = filter_by_date(raw, start, end)
    stats = generate_statistics(filtered)
    export_json(filtered, 'output.json')
    print(f'Exported {len(filtered)} entries. Stats: {stats}')

