import re
from concurrent.futures import ThreadPoolExecutor
from typing import List, Dict

PATTERN = r'^(?P<timestamp>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) \[(?P<level>\w+)\] (?P<message>.*)$'

def parse_chunk(lines: List[str]) -> List[Dict[str, str]]:
    results = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        m = re.match(PATTERN, line)
        if m:
            results.append(m.groupdict())
    return results

def read_in_chunks(filepath: str, chunk_size: int = 1000) -> List[List[str]]:
    with open(filepath, 'r') as f:
        chunk = []
        for line in f:
            chunk.append(line)
            if len(chunk) >= chunk_size:
                yield chunk
                chunk = []
        if chunk:
            yield chunk

def parse_file_concurrent(filepath: str, max_workers: int = 4) -> List[Dict[str, str]]:
    all_results = []
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = [executor.submit(parse_chunk, chunk) for chunk in read_in_chunks(filepath)]
        for future in futures:
            all_results.extend(future.result())
    return all_results

if __name__ == '__main__':
    data = parse_file_concurrent('large_server.log')
    print(f'Parsed {len(data)} lines concurrently.')

