import argparse
import sys
import json
from datetime import datetime

def parse_args(argv=None):
    parser = argparse.ArgumentParser(description='Log parsing automation tool')
    parser.add_argument('-i', '--input', default='server.log', help='Input log file path')
    parser.add_argument('-o', '--output', default='output', help='Output file path without extension')
    parser.add_argument('-f', '--format', choices=['json', 'csv'], default='json', help='Output format')
    parser.add_argument('-s', '--start', default=None, help='Start date in YYYY-MM-DD HH:MM:SS')
    parser.add_argument('-e', '--end', default=None, help='End date in YYYY-MM-DD HH:MM:SS')
    parser.add_argument('-v', '--verbose', action='store_true', help='Enable verbose logging')
    return parser.parse_args(argv)

def main(argv=None):
    args = parse_args(argv)
    start_dt = None
    end_dt = None
    if args.start:
        start_dt = datetime.strptime(args.start, '%Y-%m-%d %H:%M:%S')
    if args.end:
        end_dt = datetime.strptime(args.end, '%Y-%m-%d %H:%M:%S')

    if args.verbose:
        print(f'Reading {args.input}...')
    data = parse_log_file(args.input)
    filtered = filter_by_date(data, start_dt, end_dt)

    if args.format == 'json':
        export_json(filtered, f'{args.output}.json')
    else:
        export_csv(filtered, f'{args.output}.csv')
    if args.verbose:
        print(f'Exported {len(filtered)} entries to {args.output}.{args.format}')

if __name__ == '__main__':
    main()

